163	     5	import java.math.RoundingMode;
164	     6	import java.time.LocalDate;
165	     7	import java.time.Month;
166	     8	
167	     9	/**
168	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
169	    11	 * high-season nights; the rate plan then decides the price from those nights. Money is rounded to cents
170	    12	 * (half-even) at every step.
171	    13	 */
172	    14	public final class PriceCalculator {
173	    15	
174	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
175	    17	
176	    18	    private final RatePlans ratePlans;
177	    19	
178	    20	    public PriceCalculator(RatePlans ratePlans) {
179	    21	        this.ratePlans = ratePlans;
180	    22	    }
181	    23	
182	    24	    /** Throws INVALID_REQUEST when the rate plan does not allow this stay. */
183	    25	    public Price calculate(Room room, NewReservation request) {
184	    26	        RatePlanPolicy plan = ratePlans.policyFor(request.ratePlan());
185	    27	        plan.validate(room, request);
186	    28	        return plan.price(room, request, nightlyCharges(room, request.checkIn(), request.checkOut()));
187	    29	    }
188	    30	
189	    31	    NightlyCharges nightlyCharges(Room room, LocalDate checkIn, LocalDate checkOut) {
190	    32	        int nights = 0;
191	    33	        BigDecimal subtotal = cents(BigDecimal.ZERO);
192	    34	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
193	    35	            subtotal = subtotal.add(nightPrice(room, night));
194	    36	            nights++;
195	    37	        }
196	    38	        return new NightlyCharges(nights, subtotal);
197	    39	    }
198	    40	
199	    41	    BigDecimal nightPrice(Room room, LocalDate night) {
200	    42	        BigDecimal nightlyRate = room.nightlyRate();
201	    43	        if (isHighSeason(night)) {
202	    44	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
203	    45	        }
204	    46	        return cents(nightlyRate);
205	    47	    }
206	    48	
207	    49	    /** High season: from December 15 to the end of February, and the whole of July. */
208	    50	    static boolean isHighSeason(LocalDate date) {
209	    51	        Month month = date.getMonth();
210	    52	        return month == Month.JANUARY
211	    53	                || month == Month.FEBRUARY
212	    54	                || month == Month.JULY
213	    55	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
214	    56	    }
215	    57	
216	    58	    static BigDecimal cents(BigDecimal value) {
217	    59	        return value.setScale(2, RoundingMode.HALF_EVEN);
218	    60	    }
219	    61	}
