     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan then decides the price from those nights. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    private final RatePlans ratePlans;
    19	
    20	    public PriceCalculator(RatePlans ratePlans) {
    21	        this.ratePlans = ratePlans;
    22	    }
    23	
    24	    /** Throws INVALID_REQUEST when the rate plan does not allow this stay. */
    25	    public Price calculate(Room room, NewReservation request) {
    26	        RatePlanPolicy plan = ratePlans.policyFor(request.ratePlan());
    27	        plan.validate(room, request);
    28	        return plan.price(room, request, nightlyCharges(room, request.checkIn(), request.checkOut()));
    29	    }
    30	
    31	    NightlyCharges nightlyCharges(Room room, LocalDate checkIn, LocalDate checkOut) {
    32	        int nights = 0;
    33	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    34	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    35	            subtotal = subtotal.add(nightPrice(room, night));
    36	            nights++;
    37	        }
    38	        return new NightlyCharges(nights, subtotal);
    39	    }
    40	
    41	    BigDecimal nightPrice(Room room, LocalDate night) {
    42	        BigDecimal nightlyRate = room.nightlyRate();
    43	        if (isHighSeason(night)) {
    44	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    45	        }
    46	        return cents(nightlyRate);
    47	    }
    48	
    49	    /** High season: from December 15 to the end of February, and the whole of July. */
    50	    static boolean isHighSeason(LocalDate date) {
    51	        Month month = date.getMonth();
    52	        return month == Month.JANUARY
    53	                || month == Month.FEBRUARY
    54	                || month == Month.JULY
    55	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    56	    }
    57	
    58	    static BigDecimal cents(BigDecimal value) {
    59	        return value.setScale(2, RoundingMode.HALF_EVEN);
    60	    }
    61	}
